/**
 * The SFX engine contract (docs/EDITOR.md §15.1): about 150 procedural sound effects in 20 categories, generated by
 * code (no recordings, no licences), seeded and deterministic, levelled to −16 LUFS with true peak ≤ −1 dBTP, saved
 * as 24-bit WAVs in the edit and imported as media. Node-safe: the tests and auto SFX import this module as it is.
 */
import { integratedLufs } from "./level.ts";

export type { SfxCategory, SfxParam, SfxPreset, SfxTag } from "./types.ts";
export { SFX_TAGS } from "./types.ts";
export {
  DEFAULT_SEED, isCustom, renderSfx, renderSfxInfo, resolveValues, SFX_CATEGORIES, SFX_ENGINE_VERSION, SFX_PRESETS, SFX_SAMPLE_RATE, sfxDefaults, sfxKey,
  sfxPreset, sfxSeconds,
} from "./engine.ts";
export { decodeWav, encodeWav } from "./wav.ts";
export { peaksOf as sfxPeaks, truePeakDb as sfxTruePeak } from "./level.ts";
export {
  addSfxMedia, ensureSfxMedia, placeSfx, prepareSfxMedia, setSfxRenderer, SFX_BIN, SFX_TRACK, sfxFileName, sfxMediaName, sfxTrack,
  type PlaceSfxOpts, type SfxRenderer,
} from "./media.ts";

/** Integrated loudness (LUFS, ITU-R BS.1770-4 with gating; a sound shorter than 400 ms counts as one block), for auto
 *  levels. */
export function sfxLoudness(ch: Float32Array[], sampleRate: number): number {
  return integratedLufs(ch, sampleRate);
}
